import static org.mockito.Mockito.*;

public class UrlBuilderTest {

    @Test
    public void newUrlBuilder_withNullInputUrl_throwsNullPointerException() {
        assertThrows(NullPointerException.class, () -> new UrlBuilder(null));
    }

    @Test
    public void newUrlBuilder_withEmptyQuery_andNoRef BuildsCorrectly() {
        URL inputUrl = new URL("http://example.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertNotNull(builder.u);
        assertTrue(builder.q == null || builder.q.toString().isEmpty());
    }

    @Test
    public void newUrlBuilder_withNonEmptyQuery_andNoRef_BuildsCorrectly() {
        URL inputUrl = new URL("http://example.com?query=foo");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertNotNull(builder.u);
        assertTrue(builder.q != null && !builder.q.toString().isEmpty());
    }

    @Test
    public void newUrlBuilder_withEmptyRef_BuildsCorrectly() {
        URL inputUrl = new URL("http://example.com#ref");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertNotNull(builder.u);
        assertTrue(builder.u.getRef() == null || builder.u.getRef().isEmpty());
    }

    @Test
    public void newUrlBuilder_withNonEmptyRef_BuildsCorrectly() {
        URL inputUrl = new URL("http://example.com#ref");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertNotNull(builder.u);
        assertTrue(builder.u.getRef() != null && !builder.u.getRef().isEmpty());
    }

    @Test
    public void build_urlWithNonAsciiPath_BuildsCorrectly() {
        URL inputUrl = new URL("http://example.com/path?query=foo#ref");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertNotNull(builder.u);
        assertTrue(StringUtil.isASCII(builder.u.getAuthority()));
    }

    @Test
    public void build_urlWithNonAsciiHost_BuildsCorrectly() {
        URL inputUrl = new URL("http://example.com/path?query=foo#ref");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertNotNull(builder.u);
        assertTrue(StringUtil.isASCII(builder.u.getHost()));
    }

    @Test
    public void appendKeyVal_withEmptyConnectionAddsQueryParameter() {
        Connection.KeyVal kv = new Connection.KeyVal();
        UrlBuilder builder = new UrlBuilder(null);
        builder.appendKeyVal(kv);
        assertNotNull(builder.q);
        assertTrue(builder.q.toString().startsWith("?"));
    }

    @Test
    public void appendKeyVal_withNonEmptyConnectionAddsQueryParameter() {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        UrlBuilder builder = new UrlBuilder(null);
        builder.appendKeyVal(kv);
        assertNotNull(builder.q);
        assertTrue(builder.q.toString().contains("?"));
    }

    @Test
    public void decodePart_withEncodedString_ReturnsDecodedString() {
        String encoded = "http%3A%2F%2Fexample.com";
        assertEquals("http://example.com", UrlBuilder.decodePart(encoded));
    }

    @Test
    public void normalizeQuery_withQueryString_ReturnsNormalizedString() {
        String q = " foo=bar ";
        assertEquals("+foo=bar", UrlBuilder.normalizeQuery(q));
    }

    @Test
    public void normalizeRef_withEncodedReference_ReturnsDecodedReference() {
        String r = "%20example.com";
        assertEquals(" example.com", UrlBuilder.normalizeRef(r));
    }
}
